#include "PhysicsWorld.h"
#include <cstdio>
int main(){PhysicsWorld impact;impact.Init();constexpr float dt=1.f/60;impact.CreateStaticBox({0,-.5,0},{5,.5,5},.6,0);auto crate=impact.CreateDynamicBox({0,.5,0},{.5,.5,.5},1,.6,0);for(int i=0;i<180;++i){impact.ApplyLinearAcceleration(crate,{0,-9.81,0},dt);impact.Step(dt);}const bool before=impact.IsSleeping(crate);auto falling=impact.CreateDynamicSphere({0,1.202f,0},.2f,1,.6f,0);impact.ApplyLinearAcceleration(crate,{0,-9.81,0},dt);impact.ApplyLinearAcceleration(falling,{0,-9.81,0},dt);impact.Step(dt);std::printf("beforeSleeping=%d afterSleeping=%d impactEvents=%zu crateY=%.9g sphereY=%.9g sphereVy=%.9g\n",before,impact.IsSleeping(crate),impact.LastStepStats().impactEvents,impact.GetTransform(crate).position.y,impact.GetTransform(falling).position.y,impact.GetLinearVelocity(falling).y);}
